insert into public.relatorios (id, fonte, data_referencia, data_divulgacao, rotulo, situacao, metadados) values ('ipea-cc70', 'ipea', '2026-04-09', '2026-04-09', 'nº 70, 1º trimestre de 2026', 'carregado', '{"titulo":"Carta de Conjuntura nº 70 — Nota de Conjuntura 26 — Visão geral da conjuntura","instituicao":"Instituto de Pesquisa Econômica Aplicada (Ipea)","periodo":"1º trimestre de 2026","publicacao":"9 de abril de 2026","url":"https://www.ipea.gov.br/cartadeconjuntura/","citacao":"SANTOS, Claudio Hamilton Matos dos; AMITRANO, Cláudio Roberto; ARAUJO, Mônica Mora y. Visão geral da conjuntura. Carta de Conjuntura, Brasília: Ipea, n. 70, Nota de Conjuntura 26, 1º trim. 2026.","nota":"Data de divulgação conforme a capa do arquivo (09/04/2026). Edição anterior ao arquivo de apoio do Estudo de Caso 2, carregada como base de comparação das projeções.","temas":["Atividade","Projeções PIB","Preços","Juros e câmbio","Trabalho e renda","Crédito e famílias","Fiscal","Setor externo"],"argumentos":[{"titulo":"Pouso suave em 2025","texto":"O PIB fechou 2025 com alta de 2,3% e cresceu 0,2% no quarto trimestre: sem ruptura do nível de atividade, mas com clara perda de tração da demanda interna.","pagina":1},{"titulo":"Início do ciclo de queda da Selic","texto":"O Copom reduziu a Selic de 15% para 14,75% em março de 2026; o ritmo e a extensão do ciclo seguem indefinidos por causa da incerteza externa.","pagina":1},{"titulo":"Guerra e petróleo","texto":"O conflito entre Estados Unidos, Israel e Irã elevou o petróleo. Os impactos são difíceis de antecipar, mas o Ipea vê motivos para otimismo moderado quanto aos efeitos sobre a economia brasileira.","pagina":2},{"titulo":"Fiscal sem variações abruptas","texto":"A expectativa de mercado era de déficit primário do governo central de 0,49% do PIB em 2026, ante 0,45% em 2025.","pagina":3},{"titulo":"Inflação: projeção mantida, composição diferente","texto":"A projeção do IPCA para 2026 foi mantida em 4,2%: o alívio de safra, câmbio e serviços foi compensado pela pressão do petróleo.","pagina":5},{"titulo":"Investimento em retração em 2026","texto":"Com carregamento estatístico de -3,2%, o Ipea projetava queda de 1,1% do investimento em 2026, mesmo com alguma recuperação ao longo do ano, e alta de 3,1% em 2027.","pagina":18}],"numero":70,"curto":"Carta de Conjuntura nº 70","curtoNota":"Carta de Conjuntura nº 70, Nota de Conjuntura 26"}'::jsonb);
