insert into public.relatorios (id, fonte, data_referencia, data_divulgacao, rotulo, situacao, metadados) values ('ipea-cc72', 'ipea', '2026-10-15', '2026-10-15', 'nº 72, 3º trimestre de 2026', 'carregado', '{"titulo":"Carta de Conjuntura nº 72 — Nota de Conjuntura 23 — Visão geral da conjuntura","instituicao":"Instituto de Pesquisa Econômica Aplicada (Ipea)","periodo":"3º trimestre de 2026","publicacao":"15 de outubro de 2026","url":"https://www.ipea.gov.br/cartadeconjuntura/","citacao":"SANTOS, Claudio Hamilton Matos dos; AMITRANO, Cláudio Roberto; ARAUJO, Mônica Mora y. Visão geral da conjuntura. Carta de Conjuntura, Brasília: Ipea, n. 72, Nota de Conjuntura 23, 3º trim. 2026.","nota":"Data de divulgação conforme a capa do arquivo (15/10/2026). A tabela 6.2 traz Selic de 12,50% (2026) e 11,00% (2027), mas o texto da mesma página menciona hipóteses de 13,5% e 11,5%: confira no original antes de citar.","temas":["Atividade","Projeções PIB","Preços","Juros e câmbio","Trabalho e renda","Crédito e famílias","Fiscal","Setor externo"],"argumentos":[{"titulo":"Desaceleração que não estava prevista","texto":"Os dados do terceiro trimestre indicam perda de ritmo, e o Ipea passou a esperar para 2026 um crescimento um pouco menor que o de 2025: a projeção do PIB caiu de 2,3% para 2,0%.","pagina":1},{"titulo":"Retomada esperada no quarto trimestre","texto":"Agropecuária e indústria extrativa, gastos sociais elevados e o mercado de trabalho ainda dinâmico sustentam um otimismo moderado para o fim do ano.","pagina":1},{"titulo":"Crédito responde pouco à Selic","texto":"Após quase dois anos de juros reais altos, o saldo do crédito livre a pessoas físicas ainda crescia 5,8% em termos reais em agosto de 2026; a desaceleração tem sido muito suave.","pagina":2},{"titulo":"Serviço da dívida freia o consumo","texto":"O consumo das famílias caiu 0,4% no segundo trimestre. O comprometimento da renda com o serviço da dívida subiu e reduz a parcela disponível para outros gastos, efeito reforçado pelas apostas online.","pagina":2},{"titulo":"Mercado de trabalho em moderação gradual","texto":"Com desocupação próxima de 5%, não se espera que a massa salarial siga crescendo no ritmo dos últimos quatro anos, mas tampouco se antecipam surpresas negativas.","pagina":3},{"titulo":"Choque do petróleo mais duradouro","texto":"O conflito no Oriente Médio deve durar mais do que se previa: o Brent voltou a superar US$ 100, e a agência de energia dos EUA elevou suas projeções de preço.","pagina":4},{"titulo":"Fiscal: curto prazo estável, ajuste provável em 2027","texto":"O déficit primário esperado recuou para 0,4% do PIB em 2026 e 2027, mas a dívida pública segue em alta e o Ipea considera prováveis ajustes nas despesas obrigatórias.","pagina":4},{"titulo":"Inflação em queda, com riscos de alta","texto":"O IPCA em doze meses recuou de 4,7% para 4,2% entre maio e agosto, e a projeção para 2026 caiu de 5,3% para 5,0%. Petróleo, clima e câmbio são os principais riscos.","pagina":24}],"numero":72,"curto":"Carta de Conjuntura nº 72","curtoNota":"Carta de Conjuntura nº 72, Nota de Conjuntura 23"}'::jsonb);
